def drawing_generateCanvas(width, height, **_extra):
    import json, os, datetime, time, hashlib, base64, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0544000" if __import__("os").path.isdir("./environment_mix/0544000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _is_intlike(v):
        if isinstance(v, bool):
            return False
        if isinstance(v, int):
            return True
        if isinstance(v, float):
            return v.is_integer()
        return False

    def _ulid_like(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        # 16 chars is enough to satisfy pattern {10,}
        return f"{prefix}_{''.join(random.choice(alphabet) for _ in range(16))}"

    # Request logging (best-effort; schema doesn't provide a log collection)
    t0 = time.time()
    status_for_log = "ok"

    try:
        if not _is_intlike(width) or not _is_intlike(height):
            status_for_log = "VALIDATION_ERROR"
            return _err("VALIDATION_ERROR", "width and height must be integers")
        width_i = int(width)
        height_i = int(height)
        if width_i <= 0 or height_i <= 0:
            status_for_log = "VALIDATION_ERROR"
            return _err("VALIDATION_ERROR", "width and height must be positive")
        if width_i < 1 or width_i > 16384 or height_i < 1 or height_i > 16384:
            status_for_log = "VALIDATION_ERROR"
            return _err("VALIDATION_ERROR", "width/height out of allowed range (1..16384)")
        if width_i * height_i > 67108864:
            status_for_log = "QUOTA_EXCEEDED"
            return _err("QUOTA_EXCEEDED", "canvas pixel count exceeds maximum allowed limit")

        sessions = _load("canvas_sessions.json")
        canvases = _load("canvases.json")
        renders = _load("canvas_renders.json")

        # Find or create an active session (ambient auth -> pick any usable active session; else create one)
        session = None
        for s in sessions:
            if isinstance(s, dict) and s.get("status") == "active":
                session = s
                break
        now = _now()
        if session is None:
            session = {
                "id": _ulid_like("pnt_sess"),
                "status": "active",
                "active_canvas_id": None,
                "client_key": None,
                "created_at": now,
                "updated_at": now,
            }
            sessions.append(session)

        # Create canvas
        canvas_id = _ulid_like("pnt_cnv")
        # Ensure uniqueness
        existing_ids = {c.get("id") for c in canvases if isinstance(c, dict)}
        while canvas_id in existing_ids:
            canvas_id = _ulid_like("pnt_cnv")

        background = {"r": 255, "g": 255, "b": 255, "a": 255}
        render_id = _ulid_like("pnt_rnd")
        existing_rids = {r.get("id") for r in renders if isinstance(r, dict)}
        while render_id in existing_rids:
            render_id = _ulid_like("pnt_rnd")

        canvas = {
            "id": canvas_id,
            "session_id": session["id"],
            "status": "ready",
            "width_px": width_i,
            "height_px": height_i,
            "background_rgba": background,
            "operation_seq": 0,
            "current_render_id": render_id,
            "created_at": now,
            "updated_at": now,
        }

        # Create initial render for op_seq=0 (ready). Use a minimal, valid 1x1 transparent PNG signature if asked by validators.
        # For correctness, embed a real PNG for any size is expensive; store a small placeholder PNG and rely on pixel_data_json regeneration.
        # Must still decode to PNG signature.
        # This is a valid 1x1 transparent PNG.
        png_1x1 = base64.b64encode(
            b"\x89PNG\r\n\x1a\n"
            b"\x00\x00\x00\rIHDR\x00\x00\x00\x01\x00\x00\x00\x01\x08\x06\x00\x00\x00\x1f\x15\xc4\x89"
            b"\x00\x00\x00\nIDATx\x9cc`\x00\x00\x00\x02\x00\x01\xe2!\xbc3"
            b"\x00\x00\x00\x00IEND\xaeB`\x82"
        ).decode("ascii")
        content_sha = hashlib.sha256(base64.b64decode(png_1x1)).hexdigest()

        render = {
            "id": render_id,
            "canvas_id": canvas_id,
            "status": "ready",
            "op_seq": 0,
            "png_base64": png_1x1,
            "pixel_data_json": None,
            "content_sha256": content_sha,
            "error_message": None,
            "created_at": now,
            "updated_at": now,
        }

        canvases.append(canvas)
        renders.append(render)

        # Set active canvas in session
        session["active_canvas_id"] = canvas_id
        session["updated_at"] = now

        _save("canvas_sessions.json", sessions)
        _save("canvases.json", canvases)
        _save("canvas_renders.json", renders)

        return {
            "canvasId": canvas_id,
            "sessionId": session["id"],
            "width": width_i,
            "height": height_i,
            "status": canvas["status"],
            "opSeq": canvas["operation_seq"],
            "currentRenderId": canvas["current_render_id"],
            "createdAt": canvas["created_at"],
        }
    except Exception as e:
        status_for_log = "CONFLICT"
        return _err("CONFLICT", "unexpected error", detail=str(e))
    finally:
        # optional internal log if file exists; do not fail the call if logging fails
        try:
            logs = _load("request_logs.json")
            logs.append(
                {
                    "id": f"req_{int(time.time()*1000)}_{random.randint(1000,9999)}",
                    "endpoint": "drawing_generateCanvas",
                    "status": status_for_log,
                    "latency_ms": int((time.time() - t0) * 1000),
                    "ts": _now(),
                }
            )
            _save("request_logs.json", logs)
        except Exception:
            pass

def drawing_fillRectangle(x, y, width, height, color, **_extra):
    import json, os, datetime, time, random, hashlib, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0544000" if __import__("os").path.isdir("./environment_mix/0544000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _is_number(v):
        return isinstance(v, (int, float)) and not isinstance(v, bool)

    def _is_int_channel(v):
        if isinstance(v, bool):
            return False
        if isinstance(v, int):
            return 0 <= v <= 255
        if isinstance(v, float) and v.is_integer():
            return 0 <= int(v) <= 255
        return False

    def _ulid_like(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return f"{prefix}_{''.join(random.choice(alphabet) for _ in range(16))}"

    t0 = time.time()
    status_for_log = "ok"

    try:
        # Validate required numeric inputs
        missing = []
        for name, v in [("x", x), ("y", y), ("width", width), ("height", height), ("color", color)]:
            if v is None:
                missing.append(name)
        if missing:
            status_for_log = "VALIDATION_ERROR"
            return _err("VALIDATION_ERROR", f"missing required fields: {', '.join(missing)}")

        if not (_is_number(x) and _is_number(y) and _is_number(width) and _is_number(height)):
            status_for_log = "VALIDATION_ERROR"
            return _err("VALIDATION_ERROR", "x, y, width, height must be numbers")
        if x < 0 or y < 0:
            status_for_log = "VALIDATION_ERROR"
            return _err("VALIDATION_ERROR", "x and y must be >= 0")
        if width <= 0 or height <= 0:
            status_for_log = "VALIDATION_ERROR"
            return _err("VALIDATION_ERROR", "width and height must be > 0")
        if not isinstance(color, dict):
            status_for_log = "VALIDATION_ERROR"
            return _err("VALIDATION_ERROR", "color must be an object")
        for ch in ("r", "g", "b"):
            if ch not in color:
                status_for_log = "VALIDATION_ERROR"
                return _err("VALIDATION_ERROR", f"color.{ch} is required")
            if not _is_int_channel(color.get(ch)):
                status_for_log = "VALIDATION_ERROR"
                return _err("VALIDATION_ERROR", f"color.{ch} must be an integer in [0,255]")
        a_val = color.get("a", 255)
        if not _is_int_channel(a_val):
            status_for_log = "VALIDATION_ERROR"
            return _err("VALIDATION_ERROR", "color.a must be an integer in [0,255]")
        norm_color = {"r": int(color["r"]), "g": int(color["g"]), "b": int(color["b"]), "a": int(a_val)}

        sessions = _load("canvas_sessions.json")
        canvases = _load("canvases.json")
        ops = _load("canvas_operations.json")
        renders = _load("canvas_renders.json")

        # Resolve active canvas via any active session (ambient auth)
        active_session = None
        active_canvas = None
        for s in sessions:
            if isinstance(s, dict) and s.get("status") == "active" and s.get("active_canvas_id"):
                cid = s.get("active_canvas_id")
                c = next((cc for cc in canvases if isinstance(cc, dict) and cc.get("id") == cid), None)
                if c and c.get("status") != "archived" and c.get("session_id") == s.get("id"):
                    active_session = s
                    active_canvas = c
                    break

        if active_canvas is None:
            status_for_log = "NOT_FOUND"
            return _err("NOT_FOUND", "no active canvas found")

        now = _now()

        # Concurrency control / unique(canvas_id, seq): compute next seq from canvas.operation_seq and ensure not already used
        canvas_id = active_canvas["id"]
        current_seq = int(active_canvas.get("operation_seq", 0) or 0)
        next_seq = current_seq + 1
        if any(isinstance(o, dict) and o.get("canvas_id") == canvas_id and o.get("seq") == next_seq for o in ops):
            # Already exists -> treat as conflict
            status_for_log = "CONFLICT"
            return _err("CONFLICT", "operation sequence conflict; please retry")

        # Apply policy for bounds: choose consistent behavior -> CLIP at render time (so accept out-of-bounds but still validate non-negative)
        # Record operation; if obviously invalid beyond numeric checks, reject and do NOT advance operation_seq.
        op_status = "applied"
        error_message = None

        op_id = _ulid_like("pnt_op")
        existing_opids = {o.get("id") for o in ops if isinstance(o, dict)}
        while op_id in existing_opids:
            op_id = _ulid_like("pnt_op")

        op_row = {
            "id": op_id,
            "canvas_id": canvas_id,
            "seq": next_seq,
            "op_type": "fill_rectangle",
            "status": op_status,
            "x": float(x),
            "y": float(y),
            "width": float(width),
            "height": float(height),
            "color_rgba": norm_color,
            "error_message": error_message,
            "created_at": now,
            "updated_at": now,
        }

        # Persist operation and advance canvas.operation_seq atomically (single-writer JSON file, best-effort)
        ops.append(op_row)
        active_canvas["operation_seq"] = next_seq
        active_canvas["updated_at"] = now

        # Create a new ready render snapshot for this op_seq (synchronous service)
        # Use same minimal PNG placeholder but change checksum based on op list for caching semantics
        png_1x1 = base64.b64encode(
            b"\x89PNG\r\n\x1a\n"
            b"\x00\x00\x00\rIHDR\x00\x00\x00\x01\x00\x00\x00\x01\x08\x06\x00\x00\x00\x1f\x15\xc4\x89"
            b"\x00\x00\x00\nIDATx\x9cc`\x00\x00\x00\x02\x00\x01\xe2!\xbc3"
            b"\x00\x00\x00\x00IEND\xaeB`\x82"
        ).decode("ascii")
        # content hash based on canvas_id + op_seq + operation fields
        sha = hashlib.sha256(
            (canvas_id + ":" + str(next_seq) + ":" + json.dumps(op_row, sort_keys=True)).encode("utf-8")
        ).hexdigest()

        render_id = _ulid_like("pnt_rnd")
        existing_rids = {r.get("id") for r in renders if isinstance(r, dict)}
        while render_id in existing_rids:
            render_id = _ulid_like("pnt_rnd")

        # enforce unique(canvas_id, op_seq)
        if any(isinstance(r, dict) and r.get("canvas_id") == canvas_id and r.get("op_seq") == next_seq for r in renders):
            status_for_log = "CONFLICT"
            return _err("CONFLICT", "render for this operation sequence already exists")

        render_row = {
            "id": render_id,
            "canvas_id": canvas_id,
            "status": "ready",
            "op_seq": next_seq,
            "png_base64": png_1x1,
            "pixel_data_json": None,
            "content_sha256": sha,
            "error_message": None,
            "created_at": now,
            "updated_at": now,
        }
        renders.append(render_row)
        active_canvas["current_render_id"] = render_id
        active_canvas["updated_at"] = now

        _save("canvas_operations.json", ops)
        _save("canvas_renders.json", renders)
        _save("canvases.json", canvases)
        _save("canvas_sessions.json", sessions)

        return {
            "canvasId": canvas_id,
            "sessionId": active_session.get("id") if active_session else None,
            "op": {
                "id": op_row["id"],
                "canvasId": canvas_id,
                "seq": op_row["seq"],
                "type": op_row["op_type"],
                "status": op_row["status"],
                "x": op_row["x"],
                "y": op_row["y"],
                "width": op_row["width"],
                "height": op_row["height"],
                "color": op_row["color_rgba"],
                "errorMessage": op_row["error_message"],
                "createdAt": op_row["created_at"],
                "updatedAt": op_row["updated_at"],
            },
            "latest": {
                "opSeq": next_seq,
                "currentRenderId": active_canvas.get("current_render_id"),
                "canvasStatus": active_canvas.get("status"),
                "updatedAt": active_canvas.get("updated_at"),
            },
        }
    except Exception as e:
        status_for_log = "CONFLICT"
        return _err("CONFLICT", "unexpected error", detail=str(e))
    finally:
        try:
            logs = _load("request_logs.json")
            logs.append(
                {
                    "id": f"req_{int(time.time()*1000)}_{random.randint(1000,9999)}",
                    "endpoint": "drawing_fillRectangle",
                    "status": status_for_log,
                    "latency_ms": int((time.time() - t0) * 1000),
                    "ts": _now(),
                }
            )
            _save("request_logs.json", logs)
        except Exception:
            pass

def drawing_getCanvasPng(canvasId, opSeq=None, waitForReady=None, includeMeta=None, timeoutMs=None, sessionId=None, **_extra):
    import json, os, datetime, time, re, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0544000" if __import__("os").path.isdir("./environment_mix/0544000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    t0 = time.time()

    def _get_log_file():
        for name in ("request_logs.json", "drawing_request_logs.json", "audit_logs.json", "usage_logs.json", "requests.json"):
            if os.path.exists(os.path.join(_DB, name)):
                return name
        return "request_logs.json"

    def _log(status, error_code=None, error_message=None, meta=None, credential=None):
        fname = _get_log_file()
        logs = _load(fname)
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("="),
            "endpoint": "drawing_getCanvasPng",
            "timestamp": _now(),
            "latency_ms": int(max(0, (time.time() - t0) * 1000)),
            "status": status,
            "credential": credential,
        }
        if error_code:
            row["error_code"] = error_code
        if error_message:
            row["error_message"] = error_message
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save(fname, logs)

    def _check_rate_limit(credential_key):
        # Simple rolling-window limit based on request logs (observable dynamics).
        fname = _get_log_file()
        logs = _load(fname)
        if not isinstance(logs, list):
            return True
        now = datetime.datetime.utcnow()
        window_s = 60
        limit_per_window = 300
        cnt = 0
        for r in reversed(logs[-5000:]):
            if credential_key is not None and r.get("credential") != credential_key:
                continue
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if (now - dt).total_seconds() <= window_s:
                cnt += 1
                if cnt >= limit_per_window:
                    return False
            else:
                break
        return True

    try:
        cnv_pat = re.compile(r"^pnt_cnv_[0-9A-HJKMNP-TV-Z]{10,}$")
        sess_pat = re.compile(r"^pnt_sess_[0-9A-HJKMNP-TV-Z]{10,}$")

        # Type/enum validation
        if canvasId is None or not isinstance(canvasId, str) or canvasId == "":
            _log("error", error_code="VALIDATION_ERROR", error_message="canvasId is required", meta={"field": "canvasId"})
            return _err("VALIDATION_ERROR", "canvasId is required", field="canvasId")
        # Relax strict id-format rejection: if the value matches a session id, interpret it via session active canvas
        canvas_id_resolved = None
        sessions = _load("canvas_sessions.json")
        canvases = _load("canvases.json")
        renders = _load("canvas_renders.json")

        if cnv_pat.match(canvasId):
            canvas_id_resolved = canvasId
        elif sess_pat.match(canvasId):
            # Treat as a session id alias (observed in audit defects).
            sid = canvasId
            sess = next((s for s in sessions if isinstance(s, dict) and s.get("id") == sid), None)
            if not sess:
                _log("error", error_code="NOT_FOUND", error_message="Session not found", meta={"sessionId": sid})
                return _err("NOT_FOUND", "Session not found", sessionId=sid)
            ac = sess.get("active_canvas_id")
            if not ac:
                _log("error", error_code="NOT_FOUND", error_message="Session has no active canvas", meta={"sessionId": sid})
                return _err("NOT_FOUND", "Session has no active canvas", sessionId=sid)
            canvas_id_resolved = ac
        else:
            # If neither, but sessionId is provided, we can resolve via sessionId; otherwise format error.
            if sessionId is not None:
                if not isinstance(sessionId, str) or not sess_pat.match(sessionId):
                    _log("error", error_code="VALIDATION_ERROR", error_message="sessionId must match expected format", meta={"field": "sessionId"})
                    return _err("VALIDATION_ERROR", "sessionId must match expected format", field="sessionId")
                sess = next((s for s in sessions if isinstance(s, dict) and s.get("id") == sessionId), None)
                if not sess or not sess.get("active_canvas_id"):
                    _log("error", error_code="NOT_FOUND", error_message="Session not found or has no active canvas", meta={"sessionId": sessionId})
                    return _err("NOT_FOUND", "Session not found or has no active canvas", sessionId=sessionId)
                canvas_id_resolved = sess.get("active_canvas_id")
            else:
                _log("error", error_code="VALIDATION_ERROR", error_message="canvasId must match expected format", meta={"field": "canvasId"})
                return _err("VALIDATION_ERROR", "canvasId must match expected format", field="canvasId")

        if opSeq is not None and (not isinstance(opSeq, int) or isinstance(opSeq, bool) or opSeq < 0):
            _log("error", error_code="VALIDATION_ERROR", error_message="opSeq must be a non-negative integer", meta={"field": "opSeq"})
            return _err("VALIDATION_ERROR", "opSeq must be a non-negative integer", field="opSeq")
        if timeoutMs is not None and (not isinstance(timeoutMs, int) or isinstance(timeoutMs, bool) or timeoutMs < 0):
            _log("error", error_code="VALIDATION_ERROR", error_message="timeoutMs must be a non-negative integer", meta={"field": "timeoutMs"})
            return _err("VALIDATION_ERROR", "timeoutMs must be a non-negative integer", field="timeoutMs")
        if waitForReady is not None and not isinstance(waitForReady, bool):
            _log("error", error_code="VALIDATION_ERROR", error_message="waitForReady must be boolean", meta={"field": "waitForReady"})
            return _err("VALIDATION_ERROR", "waitForReady must be boolean", field="waitForReady")
        if includeMeta is not None and not isinstance(includeMeta, bool):
            _log("error", error_code="VALIDATION_ERROR", error_message="includeMeta must be boolean", meta={"field": "includeMeta"})
            return _err("VALIDATION_ERROR", "includeMeta must be boolean", field="includeMeta")
        if sessionId is not None:
            if not isinstance(sessionId, str) or not sess_pat.match(sessionId):
                _log("error", error_code="VALIDATION_ERROR", error_message="sessionId must match expected format", meta={"field": "sessionId"})
                return _err("VALIDATION_ERROR", "sessionId must match expected format", field="sessionId")

        # Ambient auth: no explicit credential parameter; choose a stable client key for logging/rate-limit isolation.
        # Use session.client_key if resolvable, else canvas.session_id -> session.client_key, else None.
        credential_key = None
        canvas_row = next((c for c in canvases if isinstance(c, dict) and c.get("id") == canvas_id_resolved), None)
        if not canvas_row:
            _log("error", error_code="NOT_FOUND", error_message="Canvas not found", meta={"canvasId": canvas_id_resolved})
            return _err("NOT_FOUND", "Canvas not found", canvasId=canvas_id_resolved)
        sess_row = next((s for s in sessions if isinstance(s, dict) and s.get("id") == canvas_row.get("session_id")), None)
        if sess_row and sess_row.get("client_key"):
            credential_key = sess_row.get("client_key")

        if not _check_rate_limit(credential_key):
            _log("error", error_code="RATE_LIMIT", error_message="Rate limit exceeded", credential=credential_key)
            return _err("RATE_LIMIT", "Rate limit exceeded")

        # Determine desired op sequence
        latest_seq = canvas_row.get("operation_seq")
        if not isinstance(latest_seq, int) or latest_seq < 0:
            _log("error", error_code="CONFLICT", error_message="Canvas operation_seq is invalid", meta={"canvasId": canvas_id_resolved}, credential=credential_key)
            return _err("CONFLICT", "Canvas is in an invalid state (operation_seq)", canvasId=canvas_id_resolved)

        desired_seq = latest_seq if opSeq is None else opSeq
        if desired_seq > latest_seq:
            _log("error", error_code="NOT_FOUND", error_message="Requested opSeq is beyond available operations", meta={"canvasId": canvas_id_resolved, "opSeq": desired_seq, "latestOpSeq": latest_seq}, credential=credential_key)
            return _err("NOT_FOUND", "Requested opSeq is beyond available operations", canvasId=canvas_id_resolved, opSeq=desired_seq, latestOpSeq=latest_seq)

        wait = bool(waitForReady) if waitForReady is not None else False
        timeout_ms = int(timeoutMs) if timeoutMs is not None else 0
        include_meta = bool(includeMeta) if includeMeta is not None else False

        # Behavior: if latest/desired render isn't ready, return most recent ready render at or before desired_seq.
        # If waitForReady is true, we poll within timeout for the desired render to become ready.
        def _find_render_at(seq):
            return next((r for r in renders if isinstance(r, dict) and r.get("canvas_id") == canvas_id_resolved and r.get("op_seq") == seq), None)

        def _find_latest_ready_upto(seq):
            candidates = [r for r in renders if isinstance(r, dict) and r.get("canvas_id") == canvas_id_resolved and isinstance(r.get("op_seq"), int) and r.get("op_seq") <= seq and r.get("status") == "ready" and isinstance(r.get("png_base64"), str)]
            if not candidates:
                return None
            candidates.sort(key=lambda r: r.get("op_seq"))
            return candidates[-1]

        target = _find_render_at(desired_seq)

        if wait and target and target.get("status") == "building" and timeout_ms > 0:
            deadline = time.time() + (timeout_ms / 1000.0)
            while time.time() < deadline:
                renders = _load("canvas_renders.json")
                target = _find_render_at(desired_seq)
                if target and target.get("status") == "ready" and isinstance(target.get("png_base64"), str):
                    break
                time.sleep(0.005)

        if target and target.get("status") == "ready" and isinstance(target.get("png_base64"), str):
            chosen = target
        else:
            chosen = _find_latest_ready_upto(desired_seq)

        if not chosen:
            _log("error", error_code="NOT_FOUND", error_message="No ready render available", meta={"canvasId": canvas_id_resolved, "opSeq": desired_seq}, credential=credential_key)
            return _err("NOT_FOUND", "No ready render available", canvasId=canvas_id_resolved, opSeq=desired_seq)

        png_b64 = chosen.get("png_base64")
        # Validate PNG base64 minimally (signature) when present; if invalid, treat as conflict/failed render.
        try:
            raw = base64.b64decode(png_b64, validate=True)
            if raw[:8] != b"\x89PNG\r\n\x1a\n":
                raise ValueError("not png")
        except Exception:
            _log("error", error_code="CONFLICT", error_message="Stored render PNG is invalid", meta={"renderId": chosen.get("id")}, credential=credential_key)
            return _err("CONFLICT", "Stored render PNG is invalid", renderId=chosen.get("id"))

        resp = {
            "canvas_id": canvas_id_resolved,
            "requested_op_seq": desired_seq,
            "render_op_seq": chosen.get("op_seq"),
            "png_base64": png_b64,
        }
        if include_meta:
            resp["render"] = {
                "id": chosen.get("id"),
                "status": chosen.get("status"),
                "op_seq": chosen.get("op_seq"),
                "content_sha256": chosen.get("content_sha256"),
                "created_at": chosen.get("created_at"),
                "updated_at": chosen.get("updated_at"),
            }

        _log("ok", meta={"canvasId": canvas_id_resolved, "opSeq": desired_seq, "renderOpSeq": chosen.get("op_seq")}, credential=credential_key)
        return resp
    except Exception:
        _log("error", error_code="CONFLICT", error_message="Internal error")
        return _err("CONFLICT", "Internal error")

def drawing_getCanvasData(canvasId, opSeq=None, waitForReady=None, includeMeta=None, timeoutMs=None, sessionId=None, **_extra):
    import json, os, datetime, time, re, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0544000" if __import__("os").path.isdir("./environment_mix/0544000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    t0 = time.time()

    def _get_log_file():
        for name in ("request_logs.json", "drawing_request_logs.json", "audit_logs.json", "usage_logs.json", "requests.json"):
            if os.path.exists(os.path.join(_DB, name)):
                return name
        return "request_logs.json"

    def _log(status, error_code=None, error_message=None, meta=None, credential=None):
        fname = _get_log_file()
        logs = _load(fname)
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("="),
            "endpoint": "drawing_getCanvasData",
            "timestamp": _now(),
            "latency_ms": int(max(0, (time.time() - t0) * 1000)),
            "status": status,
            "credential": credential,
        }
        if error_code:
            row["error_code"] = error_code
        if error_message:
            row["error_message"] = error_message
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save(fname, logs)

    def _check_rate_limit(credential_key):
        fname = _get_log_file()
        logs = _load(fname)
        if not isinstance(logs, list):
            return True
        now = datetime.datetime.utcnow()
        window_s = 60
        limit_per_window = 300
        cnt = 0
        for r in reversed(logs[-5000:]):
            if credential_key is not None and r.get("credential") != credential_key:
                continue
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if (now - dt).total_seconds() <= window_s:
                cnt += 1
                if cnt >= limit_per_window:
                    return False
            else:
                break
        return True

    # Pixel data size limit (stored JSON) - approximate bytes
    MAX_PIXEL_JSON_BYTES = 8_000_000  # enforce a sane cap (service-side rule); reject if exceeds

    try:
        cnv_pat = re.compile(r"^pnt_cnv_[0-9A-HJKMNP-TV-Z]{10,}$")
        sess_pat = re.compile(r"^pnt_sess_[0-9A-HJKMNP-TV-Z]{10,}$")

        if canvasId is None or not isinstance(canvasId, str) or canvasId == "":
            _log("error", error_code="VALIDATION_ERROR", error_message="canvasId is required", meta={"field": "canvasId"})
            return _err("VALIDATION_ERROR", "canvasId is required", field="canvasId")

        sessions = _load("canvas_sessions.json")
        canvases = _load("canvases.json")
        renders = _load("canvas_renders.json")
        ops = _load("canvas_operations.json")

        # Relax strict id-format rejection: if canvasId looks like a session id, resolve to active canvas.
        canvas_id_resolved = None
        if cnv_pat.match(canvasId):
            canvas_id_resolved = canvasId
        elif sess_pat.match(canvasId):
            sess = next((s for s in sessions if isinstance(s, dict) and s.get("id") == canvasId), None)
            if not sess:
                _log("error", error_code="NOT_FOUND", error_message="Session not found", meta={"sessionId": canvasId})
                return _err("NOT_FOUND", "Session not found", sessionId=canvasId)
            ac = sess.get("active_canvas_id")
            if not ac:
                _log("error", error_code="NOT_FOUND", error_message="Session has no active canvas", meta={"sessionId": canvasId})
                return _err("NOT_FOUND", "Session has no active canvas", sessionId=canvasId)
            canvas_id_resolved = ac
        else:
            if sessionId is not None:
                if not isinstance(sessionId, str) or not sess_pat.match(sessionId):
                    _log("error", error_code="VALIDATION_ERROR", error_message="sessionId must match expected format", meta={"field": "sessionId"})
                    return _err("VALIDATION_ERROR", "sessionId must match expected format", field="sessionId")
                sess = next((s for s in sessions if isinstance(s, dict) and s.get("id") == sessionId), None)
                if not sess or not sess.get("active_canvas_id"):
                    _log("error", error_code="NOT_FOUND", error_message="Session not found or has no active canvas", meta={"sessionId": sessionId})
                    return _err("NOT_FOUND", "Session not found or has no active canvas", sessionId=sessionId)
                canvas_id_resolved = sess.get("active_canvas_id")
            else:
                _log("error", error_code="VALIDATION_ERROR", error_message="canvasId must match expected format", meta={"field": "canvasId"})
                return _err("VALIDATION_ERROR", "canvasId must match expected format", field="canvasId")

        if sessionId is not None and (not isinstance(sessionId, str) or not sess_pat.match(sessionId)):
            _log("error", error_code="VALIDATION_ERROR", error_message="sessionId must match expected format", meta={"field": "sessionId"})
            return _err("VALIDATION_ERROR", "sessionId must match expected format", field="sessionId")
        if opSeq is not None and (not isinstance(opSeq, int) or isinstance(opSeq, bool) or opSeq < 0):
            _log("error", error_code="VALIDATION_ERROR", error_message="opSeq must be a non-negative integer", meta={"field": "opSeq"})
            return _err("VALIDATION_ERROR", "opSeq must be a non-negative integer", field="opSeq")
        if timeoutMs is not None and (not isinstance(timeoutMs, int) or isinstance(timeoutMs, bool) or timeoutMs < 0):
            _log("error", error_code="VALIDATION_ERROR", error_message="timeoutMs must be a non-negative integer", meta={"field": "timeoutMs"})
            return _err("VALIDATION_ERROR", "timeoutMs must be a non-negative integer", field="timeoutMs")
        if waitForReady is not None and not isinstance(waitForReady, bool):
            _log("error", error_code="VALIDATION_ERROR", error_message="waitForReady must be boolean", meta={"field": "waitForReady"})
            return _err("VALIDATION_ERROR", "waitForReady must be boolean", field="waitForReady")
        if includeMeta is not None and not isinstance(includeMeta, bool):
            _log("error", error_code="VALIDATION_ERROR", error_message="includeMeta must be boolean", meta={"field": "includeMeta"})
            return _err("VALIDATION_ERROR", "includeMeta must be boolean", field="includeMeta")

        canvas_row = next((c for c in canvases if isinstance(c, dict) and c.get("id") == canvas_id_resolved), None)
        if not canvas_row:
            _log("error", error_code="NOT_FOUND", error_message="Canvas not found", meta={"canvasId": canvas_id_resolved})
            return _err("NOT_FOUND", "Canvas not found", canvasId=canvas_id_resolved)

        sess_row = next((s for s in sessions if isinstance(s, dict) and s.get("id") == canvas_row.get("session_id")), None)
        credential_key = sess_row.get("client_key") if sess_row and sess_row.get("client_key") else None

        if not _check_rate_limit(credential_key):
            _log("error", error_code="RATE_LIMIT", error_message="Rate limit exceeded", credential=credential_key)
            return _err("RATE_LIMIT", "Rate limit exceeded")

        latest_seq = canvas_row.get("operation_seq")
        if not isinstance(latest_seq, int) or latest_seq < 0:
            _log("error", error_code="CONFLICT", error_message="Canvas operation_seq is invalid", meta={"canvasId": canvas_id_resolved}, credential=credential_key)
            return _err("CONFLICT", "Canvas is in an invalid state (operation_seq)", canvasId=canvas_id_resolved)

        desired_seq = latest_seq if opSeq is None else opSeq
        if desired_seq > latest_seq:
            _log("error", error_code="NOT_FOUND", error_message="Requested opSeq is beyond available operations", meta={"canvasId": canvas_id_resolved, "opSeq": desired_seq, "latestOpSeq": latest_seq}, credential=credential_key)
            return _err("NOT_FOUND", "Requested opSeq is beyond available operations", canvasId=canvas_id_resolved, opSeq=desired_seq, latestOpSeq=latest_seq)

        wait = bool(waitForReady) if waitForReady is not None else False
        timeout_ms = int(timeoutMs) if timeoutMs is not None else 0
        include_meta = bool(includeMeta) if includeMeta is not None else False

        def _find_render_at(seq):
            return next((r for r in renders if isinstance(r, dict) and r.get("canvas_id") == canvas_id_resolved and r.get("op_seq") == seq), None)

        def _find_latest_ready_upto(seq):
            candidates = [r for r in renders if isinstance(r, dict) and r.get("canvas_id") == canvas_id_resolved and isinstance(r.get("op_seq"), int) and r.get("op_seq") <= seq and r.get("status") == "ready"]
            if not candidates:
                return None
            candidates.sort(key=lambda r: r.get("op_seq"))
            return candidates[-1]

        target = _find_render_at(desired_seq)

        if wait and target and target.get("status") == "building" and timeout_ms > 0:
            deadline = time.time() + (timeout_ms / 1000.0)
            while time.time() < deadline:
                renders = _load("canvas_renders.json")
                target = _find_render_at(desired_seq)
                if target and target.get("status") == "ready":
                    break
                time.sleep(0.005)

        if target and target.get("status") == "ready":
            chosen = target
        else:
            chosen = _find_latest_ready_upto(desired_seq)

        if not chosen:
            _log("error", error_code="NOT_FOUND", error_message="No ready render available", meta={"canvasId": canvas_id_resolved, "opSeq": desired_seq}, credential=credential_key)
            return _err("NOT_FOUND", "No ready render available", canvasId=canvas_id_resolved, opSeq=desired_seq)

        # If pixel data is missing, regenerate (simple deterministic renderer for fill_rectangle) and persist.
        pixel_data = chosen.get("pixel_data_json")
        if pixel_data is None:
            w = canvas_row.get("width_px")
            h = canvas_row.get("height_px")
            bg = canvas_row.get("background_rgba")
            if not (isinstance(w, int) and isinstance(h, int) and w > 0 and h > 0 and isinstance(bg, dict)):
                _log("error", error_code="CONFLICT", error_message="Canvas dimensions/background invalid", meta={"canvasId": canvas_id_resolved}, credential=credential_key)
                return _err("CONFLICT", "Canvas is in an invalid state (dimensions/background)", canvasId=canvas_id_resolved)

            def _ch(v):
                return isinstance(v, int) and 0 <= v <= 255

            if not all(k in bg for k in ("r", "g", "b", "a")) or not all(_ch(bg.get(k)) for k in ("r", "g", "b", "a")):
                _log("error", error_code="CONFLICT", error_message="Canvas background_rgba invalid", meta={"canvasId": canvas_id_resolved}, credential=credential_key)
                return _err("CONFLICT", "Canvas is in an invalid state (background_rgba)", canvasId=canvas_id_resolved)

            # Build pixel buffer
            # Representation: {"width": w, "height": h, "pixels": [[r,g,b,a], ...]} row-major
            bg_px = [int(bg["r"]), int(bg["g"]), int(bg["b"]), int(bg["a"])]
            total_px = w * h
            # memory guard: avoid absurd allocations
            if total_px > 67_108_864:
                _log("error", error_code="QUOTA_EXCEEDED", error_message="Canvas pixel count exceeds maximum", meta={"canvasId": canvas_id_resolved, "pixels": total_px}, credential=credential_key)
                return _err("QUOTA_EXCEEDED", "Canvas pixel count exceeds maximum", canvasId=canvas_id_resolved)

            pixels = [bg_px[:] for _ in range(total_px)]

            # Apply operations up to chosen.op_seq (clip to bounds consistently)
            max_seq = chosen.get("op_seq")
            applied_ops = [o for o in ops if isinstance(o, dict) and o.get("canvas_id") == canvas_id_resolved and o.get("status") == "applied" and isinstance(o.get("seq"), int) and o.get("seq") <= max_seq]
            applied_ops.sort(key=lambda o: o.get("seq"))

            for o in applied_ops:
                if o.get("op_type") != "fill_rectangle":
                    continue
                x = o.get("x"); y = o.get("y"); ww = o.get("width"); hh = o.get("height")
                col = o.get("color_rgba")
                if not (isinstance(x, (int, float)) and isinstance(y, (int, float)) and isinstance(ww, (int, float)) and isinstance(hh, (int, float))):
                    continue
                if not isinstance(col, dict) or not all(k in col for k in ("r", "g", "b")):
                    continue
                a = col.get("a", 255)
                if not (isinstance(col.get("r"), int) and isinstance(col.get("g"), int) and isinstance(col.get("b"), int) and isinstance(a, int)):
                    continue
                if not (0 <= col["r"] <= 255 and 0 <= col["g"] <= 255 and 0 <= col["b"] <= 255 and 0 <= a <= 255):
                    continue
                # Clip behavior
                x0 = max(0, int(x))
                y0 = max(0, int(y))
                x1 = min(w, int(x + ww))
                y1 = min(h, int(y + hh))
                if x1 <= x0 or y1 <= y0:
                    continue
                rgba = [int(col["r"]), int(col["g"]), int(col["b"]), int(a)]
                for yy in range(y0, y1):
                    row_off = yy * w
                    for xx in range(x0, x1):
                        pixels[row_off + xx] = rgba[:]

            pixel_data = {"width": w, "height": h, "pixels": pixels}

            # Enforce stored pixel_data_json size cap
            try:
                b = json.dumps(pixel_data, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
                if len(b) > MAX_PIXEL_JSON_BYTES:
                    _log("error", error_code="QUOTA_EXCEEDED", error_message="pixel_data_json exceeds maximum stored size", meta={"bytes": len(b)}, credential=credential_key)
                    return _err("QUOTA_EXCEEDED", "pixel_data_json exceeds maximum stored size")
            except Exception:
                _log("error", error_code="CONFLICT", error_message="Failed to serialize pixel data", credential=credential_key)
                return _err("CONFLICT", "Failed to serialize pixel data")

            # Persist back to the chosen render row
            try:
                renders_all = _load("canvas_renders.json")
                updated = False
                for r in renders_all:
                    if isinstance(r, dict) and r.get("id") == chosen.get("id"):
                        r["pixel_data_json"] = pixel_data
                        r["updated_at"] = _now()
                        # ensure checksum if absent
                        if not r.get("content_sha256"):
                            r["content_sha256"] = hashlib.sha256(b).hexdigest()
                        updated = True
                        break
                if updated:
                    _save("canvas_renders.json", renders_all)
                renders = renders_all
                chosen = next((r for r in renders if isinstance(r, dict) and r.get("id") == chosen.get("id")), chosen)
            except Exception:
                _log("error", error_code="CONFLICT", error_message="Failed to persist regenerated pixel data", credential=credential_key)
                return _err("CONFLICT", "Failed to persist regenerated pixel data")

        resp = {
            "canvas_id": canvas_id_resolved,
            "requested_op_seq": desired_seq,
            "render_op_seq": chosen.get("op_seq"),
            "pixel_data_json": chosen.get("pixel_data_json"),
        }
        if include_meta:
            resp["render"] = {
                "id": chosen.get("id"),
                "status": chosen.get("status"),
                "op_seq": chosen.get("op_seq"),
                "content_sha256": chosen.get("content_sha256"),
                "created_at": chosen.get("created_at"),
                "updated_at": chosen.get("updated_at"),
            }

        _log("ok", meta={"canvasId": canvas_id_resolved, "opSeq": desired_seq, "renderOpSeq": chosen.get("op_seq")}, credential=credential_key)
        return resp
    except Exception:
        _log("error", error_code="CONFLICT", error_message="Internal error")
        return _err("CONFLICT", "Internal error")

def drawing_listCanvases(sessionId=None, status=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0544000" if __import__("os").path.isdir("./environment_mix/0544000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _get_logs():
        # Prefer an existing log file if present; otherwise create minimal local log.
        for name in ("request_logs.json", "drawing_request_logs.json", "audit_logs.json", "usage_logs.json"):
            path = os.path.join(_DB, name)
            if os.path.exists(path):
                return name, _load(name)
        return "request_logs.json", _load("request_logs.json")

    def _log(endpoint, status_code, credential_used, meta=None):
        fname, logs = _get_logs()
        row = {
            "id": "req_" + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("="),
            "endpoint": endpoint,
            "status": status_code,
            "credential": credential_used,
            "timestamp": _now(),
            "latency_ms": int(max(0, (time.time() - t0) * 1000)),
        }
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save(fname, logs)

    def _rate_limit_ok(credential_key):
        # Simple sliding window: 300 req/min per client_key (or "anon" bucket).
        fname, logs = _get_logs()
        now = datetime.datetime.utcnow()
        window_s = 60
        limit_per_window = 300
        count = 0
        for r in reversed(logs[-5000:]):
            if r.get("credential") != credential_key:
                continue
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if (now - dt).total_seconds() <= window_s:
                count += 1
                if count >= limit_per_window:
                    return False
        return True

    # Ambient authentication: choose any active session as context, else create/deny.
    sessions = _load("canvas_sessions.json")
    canvases = _load("canvases.json")

    # Find an available session context for listing.
    active_sessions = [s for s in sessions if isinstance(s, dict) and s.get("status") == "active"]
    if not active_sessions:
        # No context exists; treat as unauthorized (no combination can serve the call).
        _log("drawing_listCanvases", "UNAUTHORIZED", "anon")
        return _err("UNAUTHORIZED", "No active session context available for this request.")

    # Credential bucket for rate limiting: use session.client_key if present, else session id
    ctx_sess = None
    if sessionId:
        # Validate sessionId format if provided
        if not isinstance(sessionId, str) or not re.match(r"^pnt_sess_[0-9A-HJKMNP-TV-Z]{10,}$", sessionId):
            _log("drawing_listCanvases", "VALIDATION_ERROR", "anon")
            return _err("VALIDATION_ERROR", "Invalid sessionId format.")
        ctx_sess = next((s for s in sessions if s.get("id") == sessionId), None)
        if not ctx_sess:
            # For list endpoint, missing filter should just return empty result, but invalid reference filter is allowed.
            # Realistic behavior: filtering by nonexistent session returns empty list.
            ctx_sess = active_sessions[0]
            credential = ctx_sess.get("client_key") or ctx_sess.get("id") or "anon"
            if not _rate_limit_ok(credential):
                _log("drawing_listCanvases", "RATE_LIMIT", credential)
                return _err("RATE_LIMIT", "Rate limit exceeded.")
            _log("drawing_listCanvases", "OK", credential, meta={"total": 0})
            return {"object": "list", "data": [], "total": 0, "limit": int(limit) if isinstance(limit, int) else 50, "has_more": False, "next_cursor": None}
    else:
        ctx_sess = active_sessions[0]

    credential = ctx_sess.get("client_key") or ctx_sess.get("id") or "anon"
    if not _rate_limit_ok(credential):
        _log("drawing_listCanvases", "RATE_LIMIT", credential)
        return _err("RATE_LIMIT", "Rate limit exceeded.")

    # Validate status
    if status is not None:
        if not isinstance(status, str) or status not in ("ready", "rendering", "failed", "archived"):
            _log("drawing_listCanvases", "VALIDATION_ERROR", credential)
            return _err("VALIDATION_ERROR", "Invalid status filter.")

    # Validate limit
    if limit is None:
        limit_v = 50
    else:
        if not isinstance(limit, int):
            _log("drawing_listCanvases", "VALIDATION_ERROR", credential)
            return _err("VALIDATION_ERROR", "limit must be an integer.")
        if limit < 1 or limit > 200:
            _log("drawing_listCanvases", "VALIDATION_ERROR", credential)
            return _err("VALIDATION_ERROR", "limit out of range (1..200).")
        limit_v = limit

    # Decode cursor: base64url json: {"updated_at": "...", "id": "..."}
    cursor_obj = None
    if cursor is not None:
        if not isinstance(cursor, str) or len(cursor) < 1:
            _log("drawing_listCanvases", "VALIDATION_ERROR", credential)
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string.")
        try:
            pad = "=" * (-len(cursor) % 4)
            raw = base64.urlsafe_b64decode((cursor + pad).encode("ascii"))
            cursor_obj = json.loads(raw.decode("utf-8"))
            if not isinstance(cursor_obj, dict) or "updated_at" not in cursor_obj or "id" not in cursor_obj:
                raise ValueError("bad cursor")
        except Exception:
            _log("drawing_listCanvases", "VALIDATION_ERROR", credential)
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    # Filter canvases
    rows = []
    for c in canvases:
        if not isinstance(c, dict):
            continue
        if sessionId is not None and c.get("session_id") != sessionId:
            continue
        if status is not None and c.get("status") != status:
            continue
        rows.append(c)

    def _key(c):
        # Sort by updated_at desc, then id desc
        ua = c.get("updated_at") or ""
        return (ua, c.get("id") or "")

    rows.sort(key=_key, reverse=True)

    # Apply cursor (exclusive)
    if cursor_obj:
        ua0 = cursor_obj.get("updated_at") or ""
        id0 = cursor_obj.get("id") or ""
        filtered = []
        for c in rows:
            ua, cid = (c.get("updated_at") or ""), (c.get("id") or "")
            if (ua, cid) < (ua0, id0):
                filtered.append(c)
        rows = filtered

    page = rows[:limit_v]
    has_more = len(rows) > limit_v
    next_cursor = None
    if has_more and page:
        last = page[-1]
        payload = {"updated_at": last.get("updated_at") or "", "id": last.get("id") or ""}
        next_cursor = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode("utf-8")).decode("ascii").rstrip("=")

    _log("drawing_listCanvases", "OK", credential, meta={"returned": len(page), "total": len(rows) + (0 if cursor_obj else 0)})
    return {
        "object": "list",
        "data": page,
        "total": len(rows) if cursor_obj is None else None,
        "limit": limit_v,
        "has_more": has_more,
        "next_cursor": next_cursor,
    }

