        return _err("VALIDATION_ERROR", "canvasId must be a non-empty string", field="canvasId")
    canvasId = canvasId.strip()

    allowed_status = {None, "queued", "applied", "rejected"}
    if status not in allowed_status:
        _append_log("error", "VALIDATION_ERROR", "status must be one of queued, applied, rejected", meta={"field": "status"}, credential=cred)
        return _err("VALIDATION_ERROR", "status must be one of queued, applied, rejected", field="status")

    if fromSeq is not None and (not isinstance(fromSeq, int) or fromSeq < 0):
        _append_log("error", "VALIDATION_ERROR", "fromSeq must be an integer >= 0", meta={"field": "fromSeq"}, credential=cred)
        return _err("VALIDATION_ERROR", "fromSeq must be an integer >= 0", field="fromSeq")
    if toSeq is not None and (not isinstance(toSeq, int) or toSeq < 0):
        _append_log("error", "VALIDATION_ERROR", "toSeq must be an integer >= 0", meta={"field": "toSeq"}, credential=cred)
        return _err("VALIDATION_ERROR", "toSeq must be an integer >= 0", field="toSeq")

    # The audit shows fromSeq > toSeq may be passed; treat as "empty window" rather than error.
    # Cursor: accept int-like string or an opaque id; do not over-validate.
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 500:
        _append_log("error", "VALIDATION_ERROR", "limit must be an integer between 1 and 500", meta={"field": "limit"}, credential=cred)
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 500", field="limit")

    canvases = _load("canvases.json")
    sessions = _load("canvas_sessions.json")
    ops = _load("canvas_operations.json")
    if not isinstance(canvases, list):
        canvases = []
    if not isinstance(sessions, list):
        sessions = []
    if not isinstance(ops, list):
        ops = []

    # Resolve canvas id (direct or via session active canvas)
    cnv = None
    for c in canvases:
        if isinstance(c, dict) and c.get("id") == canvasId:
            cnv = c
            break
    resolved_canvas_id = canvasId
    if cnv is None:
        sess = None
        for s in sessions:
            if isinstance(s, dict) and s.get("id") == canvasId:
                sess = s
                break
        if sess is not None and isinstance(sess.get("active_canvas_id"), str) and sess.get("active_canvas_id"):
            resolved_canvas_id = sess["active_canvas_id"]
            for c in canvases:
                if isinstance(c, dict) and c.get("id") == resolved_canvas_id:
                    cnv = c
                    break

    if cnv is None:
        _append_log("error", "NOT_FOUND", "Canvas not found", meta={"canvasId": canvasId}, credential=cred)
        return _err("NOT_FOUND", "Canvas not found", canvasId=canvasId)

    # Filter operations for canvas
    rows = [r for r in ops if isinstance(r, dict) and r.get("canvas_id") == resolved_canvas_id]

    if status is not None:
        rows = [r for r in rows if r.get("status") == status]

    if fromSeq is not None:
        rows = [r for r in rows if isinstance(r.get("seq"), int) and r.get("seq") >= fromSeq]
    if toSeq is not None:
        rows = [r for r in rows if isinstance(r.get("seq"), int) and r.get("seq") <= toSeq]

    # Sort ascending by seq then id (stable)
    def _sort_key(r):
        seqv = r.get("seq")
        if not isinstance(seqv, int):
            seqv = 10**18
        return (seqv, str(r.get("id", "")))

    rows.sort(key=_sort_key)

    # Cursor behavior: accept either a seq offset (int-like) meaning "start after this seq",
    # or an operation id meaning "start after this row id" (within same seq ordering).
    start_after = None
    start_after_id = None
    if cursor is not None:
        if isinstance(cursor, int):
            start_after = cursor
        elif isinstance(cursor, str):
            cs = cursor.strip()
            if cs:
                if cs.isdigit():
                    try:
                        start_after = int(cs)
                    except Exception:
                        start_after_id = cs
                else:
                    start_after_id = cs
        else:
            _append_log("error", "VALIDATION_ERROR", "cursor must be a string", meta={"field": "cursor"}, credential=cred)
            return _err("VALIDATION_ERROR", "cursor must be a string", field="cursor")

    if start_after is not None:
        rows = [r for r in rows if isinstance(r.get("seq"), int) and r.get("seq") > start_after]
    elif start_after_id is not None:
        # Find position, then slice after it
        idx = None
        for i, r in enumerate(rows):
            if r.get("id") == start_after_id:
                idx = i
                break
        if idx is not None:
            rows = rows[idx + 1 :]

    total = len(rows)
    page = rows[:limit]
    has_more = total > len(page)

    next_cursor = None
    if has_more and page:
        last = page[-1]
        if isinstance(last.get("seq"), int):
            next_cursor = str(last["seq"])
        else:
            next_cursor = str(last.get("id", "")) or None

    resp = {
        "canvas_id": resolved_canvas_id,
        "operations": page,
        "total": total,
        "limit": limit,
        "has_more": has_more,
        "next_cursor": next_cursor,
    }
    _append_log("ok", meta={"canvasId": resolved_canvas_id, "returned": len(page)}, credential=cred)
    return resp

def drawing_closeCanvasSession(sessionId, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0544000" if __import__("os").path.isdir("./environment_mix/0544000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _get_logs():
        for name in ("request_logs.json", "drawing_request_logs.json", "audit_logs.json", "usage_logs.json"):
            path = os.path.join(_DB, name)
            if os.path.exists(path):
                return name, _load(name)
        return "request_logs.json", _load("request_logs.json")

    def _log(endpoint, status_code, credential_used, meta=None):
        fname, logs = _get_logs()
        row = {
            "id": "req_" + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("="),
            "endpoint": endpoint,
            "status": status_code,
            "credential": credential_used,
            "timestamp": _now(),
            "latency_ms": int(max(0, (time.time() - t0) * 1000)),
        }
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save(fname, logs)

    def _rate_limit_ok(credential_key):
        fname, logs = _get_logs()
        now = datetime.datetime.utcnow()
        window_s = 60
        limit_per_window = 300
        count = 0
        for r in reversed(logs[-5000:]):
            if r.get("credential") != credential_key:
                continue
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if (now - dt).total_seconds() <= window_s:
                count += 1
                if count >= limit_per_window:
                    return False
        return True

    # Validate sessionId
    if not isinstance(sessionId, str) or not re.match(r"^pnt_sess_[0-9A-HJKMNP-TV-Z]{10,}$", sessionId):
        sessions = _load("canvas_sessions.json")
        ctx = next((s for s in sessions if isinstance(s, dict) and s.get("status") == "active"), None)
        cred = (ctx.get("client_key") if ctx else None) or (ctx.get("id") if ctx else None) or "anon"
        _log("drawing_closeCanvasSession", "VALIDATION_ERROR", cred)
        return _err("VALIDATION_ERROR", "Invalid sessionId format.")

    sessions = _load("canvas_sessions.json")
    # For ambient auth, pick a context that exists; for rate limiting use that client bucket if possible.
    ctx = next((s for s in sessions if isinstance(s, dict) and s.get("status") == "active"), None)
    if not ctx:
        # Still allow closing if the referenced session exists? Spec says UNAUTHORIZED if credentials missing/invalid.
        _log("drawing_closeCanvasSession", "UNAUTHORIZED", "anon")
        return _err("UNAUTHORIZED", "No active session context available for this request.")
    cred = ctx.get("client_key") or ctx.get("id") or "anon"
    if not _rate_limit_ok(cred):
        _log("drawing_closeCanvasSession", "RATE_LIMIT", cred)
        return _err("RATE_LIMIT", "Rate limit exceeded.")

    idx = None
    for i, s in enumerate(sessions):
        if isinstance(s, dict) and s.get("id") == sessionId:
            idx = i
            break
    if idx is None:
        _log("drawing_closeCanvasSession", "NOT_FOUND", cred)
        return _err("NOT_FOUND", "Session not found.")

    sess = sessions[idx]
    if sess.get("status") == "closed":
        _log("drawing_closeCanvasSession", "CONFLICT", cred)
        return _err("CONFLICT", "Session is already closed.")
    if sess.get("status") != "active":
        _log("drawing_closeCanvasSession", "INVALID_TRANSITION", cred)
        return _err("INVALID_TRANSITION", "Session cannot be closed from its current status.", from_status=sess.get("status"), to_status="closed")

    # Transition active -> closed; also clear active_canvas_id to prevent further ops via this session selection
    sess["status"] = "closed"
    sess["active_canvas_id"] = None
    sess["updated_at"] = _now()
    sessions[idx] = sess
    _save("canvas_sessions.json", sessions)

    _log("drawing_closeCanvasSession", "OK", cred, meta={"session_id": sessionId})
    return {"object": "canvas_session", "data": sess}

