    def _credential_context():
        # Ambient auth: if store has any session, treat as authorized; isolate by client_key when available.
        sessions = _load("canvas_sessions.json")
        if isinstance(sessions, list):
            for s in sessions:
                if isinstance(s, dict) and s.get("status") == "active":
                    return s.get("client_key") or "ambient"
            for s in sessions:
                if isinstance(s, dict):
