        return _err("VALIDATION_ERROR", "canvasId must be a string", canvasId=canvasId)

    pattern = r"^pnt_cnv_[0-9A-HJKMNP-TV-Z]{10,}$"
    if re.match(pattern, canvasId) is None:
        cred = _credential_context()
        _append_log(
            "error",
            "VALIDATION_ERROR",
            "canvasId must match pattern ^pnt_cnv_[0-9A-HJKMNP-TV-Z]{10,}$",
            meta={"canvasId": canvasId},
            credential=cred,
        )
        return _err(
            "VALIDATION_ERROR",
            "Invalid canvasId format; expected a canvas ULID (pnt_cnv_...).",
            canvasId=canvasId,
            pattern=pattern,
        )

    cred = _credential_context()
    ok, rate_err = _check_rate_limit(cred)
    if not ok:
        _append_log("error", rate_err["error"]["code"], rate_err["error"]["message"], meta={"canvasId": canvasId}, credential=cred)
        return rate_err

    # Load canvases
    canvases = _load("canvases.json")
    if not isinstance(canvases, list):
        canvases = []

    idx = None
    canvas = None
    for i, c in enumerate(canvases):
        if isinstance(c, dict) and c.get("id") == canvasId:
            idx = i
            canvas = c
            break

    if canvas is None:
        _append_log("error", "NOT_FOUND", "Canvas not found.", meta={"canvasId": canvasId}, credential=cred)
        return _err("NOT_FOUND", "Canvas not found.", canvasId=canvasId)

    # Enforce lifecycle transition rules
    status = canvas.get("status")
    if status == "archived":
        _append_log("error", "CONFLICT", "Canvas is already archived.", meta={"canvasId": canvasId}, credential=cred)
        return _err("CONFLICT", "Canvas is already archived.", canvasId=canvasId, status=status)

    allowed_from = {"ready", "rendering", "failed"}
    if status not in allowed_from:
        _append_log(
            "error",
            "INVALID_TRANSITION",
            "Canvas status does not allow archiving.",
            meta={"canvasId": canvasId, "from_status": status, "to_status": "archived"},
            credential=cred,
        )
        return _err(
            "INVALID_TRANSITION",
            "Illegal status transition: only ready/rendering/failed can transition to archived.",
            canvasId=canvasId,
            from_status=status,
            to_status="archived",
            allowed_from=sorted(list(allowed_from)),
        )

    # Mutate and persist: update timestamps and status
    now = _now()
    mutated = dict(canvas)
    mutated["status"] = "archived"
    mutated["updated_at"] = now
    canvases[idx] = mutated

    # If this canvas is active in its session, clear active_canvas_id (on delete set null analog; archiving -> immutable)
    sessions = _load("canvas_sessions.json")
    if not isinstance(sessions, list):
        sessions = []
    session_changed = False
    sid = mutated.get("session_id")
    if isinstance(sid, str) and sid:
        for si, s in enumerate(sessions):
            if not isinstance(s, dict):
                continue
            if s.get("id") == sid and s.get("active_canvas_id") == canvasId:
                ns = dict(s)
                ns["active_canvas_id"] = None
                ns["updated_at"] = now if isinstance(ns.get("updated_at"), str) else ns.get("updated_at") or now
                sessions[si] = ns
                session_changed = True
                break

    # Persist changes
    _save("canvases.json", canvases)
    if session_changed:
        _save("canvas_sessions.json", sessions)

    _append_log("ok", meta={"canvasId": canvasId}, credential=cred)

    return {"canvas": mutated}
